/**
 * Бинарное содержимое .docx-шаблонов, зашитое в виде Base64-строк.
 * Вынесено в отдельный файл, чтобы не раздувать 6_Module_DocxGenerator.js
 * и чтобы шаблоны было проще заменять/добавлять по отдельности.
 *
 * Шаблоны больше не подгружаются через fetch('templates/....docx') с сервера -
 * вся генерация идёт из бинарника, встроенного прямо в код.
 *
 * ВАЖНО: ниже нужно вставить реальное Base64-содержимое .docx файлов
 * (сейчас стоят заглушки-плейсхолдеры).
 *
 * Как получить Base64 из существующего .docx файла:
 *  - Node.js:
 *      node -e "console.log(require('fs').readFileSync('TemplateOrderExecuteOrPrepAudit2026.docx').toString('base64'))" > executePrep.b64
 *      node -e "console.log(require('fs').readFileSync('TemplateOrderChangeAudit2026.docx').toString('base64'))" > change.b64
 *  - Или в браузере/DevTools через FileReader.readAsDataURL() и взять часть строки после "base64,".
 *
 * Полученную строку (без переносов строк) нужно целиком вставить как значение
 * соответствующего ключа ниже. Чтобы добавить новый шаблон - просто добавьте
 * новый ключ в этот объект и используйте его как templateKey в DocxGenerator.
 */
export const TEMPLATES_BASE64 = {
    executePrep: '',
    change: ''
    };
